24	                                   const int64_t file_offset,
25	                                   const int64_t num_bytes_to_read)
26	{
27	    int64_t num_file_bytes;
28	    if (-1 == get_file_size(filename, num_file_bytes)) {
29	        const auto error_code = errno;
30	        report_file_error(filename, " fstat for read", error_code);
31	        return false;
32	    }
33	    if ((file_offset + num_bytes_to_read) > num_file_bytes) {
34	        std::cout << filename << ": file_offset + buffer nbytes > file bytes "
35	                  << (file_offset + num_bytes_to_read) << " > " << num_file_bytes << std::endl;
36	    }
37	    assert((file_offset + num_bytes_to_read) <= num_file_bytes);
38	    return true;
