51	      _num_pending_ops(0),
52	      _pinned_tensor_mgr(deepspeed_pin_tensor_t::shared())
53	{
54	    for (auto i = 0; i < intra_op_parallelism; ++i) {
55	        _thread_contexts.push_back(std::make_shared<deepspeed_aio_thread_t>(i, _aio_config));
56	    }
57	
58	    for (auto& ctxt : _thread_contexts) {
59	        _threads.push_back(std::thread(_start_aio_thread, ctxt));
