99	int deepspeed_io_handle_t::read(torch::Tensor& buffer,
100	                                const char* filename,
101	                                const bool validate,
102	                                const int64_t file_offset)
103	{
104	    const auto start_time = std::chrono::high_resolution_clock::now();
105	
106	    assert(_aio_ctxt);
107	
108	    int64_t num_file_bytes;
109	    if (-1 == get_file_size(filename, num_file_bytes)) {
110	        const auto error_code = errno;
111	        report_file_error(filename, " fstat for read", error_code);
112	        return -1;
113	    }
114	    assert(static_cast<int64_t>(buffer.nbytes()) == num_file_bytes);
115	
116	    const auto fd = open_file(filename, true);
117	    if (fd == -1) { return -1; }
118	
119	    auto read_buffer = (char*)buffer.data_ptr();
120	    std::unique_ptr<io_xfer_ctxt> xfer_ctxt(
121	        new io_xfer_ctxt(fd, file_offset, 0, num_file_bytes, read_buffer));
122	
123	    const auto error_code =
124	        _aio_config._overlap_events
125	            ? do_aio_operation_overlap(true, _aio_ctxt, xfer_ctxt, &_aio_config, nullptr)
126	            : do_aio_operation_sequential(true, _aio_ctxt, xfer_ctxt, &_aio_config, nullptr);
127	
128	    close(fd);
129	    if (error_code != 0) {
130	        report_file_error(filename, " read", -error_code);
131	        return -1;
132	    }
133	    const std::chrono::duration<double> aio_time =
134	        std::chrono::high_resolution_clock::now() - start_time;
135	
136	    if (validate) { validate_aio_operation(true, filename, read_buffer, num_file_bytes); }
137	    const std::chrono::duration<double> fn_time =
138	        std::chrono::high_resolution_clock::now() - start_time;
139	    std::cout << "Elapsed time(usec): " << "aio = " << aio_time.count() * 1e6
140	              << " call = " << fn_time.count() * 1e6 << std::endl;
141	    return 0;
142	}
