184	void deepspeed_io_handle_t::_schedule_aio_work_locked(
185	    std::shared_ptr<struct io_op_desc_t> scheduled_op)
186	{
187	    for (auto& ctxt : _thread_contexts) {
188	        {
189	            std::lock_guard<std::mutex> lock(ctxt->_work_sync._mutex);
190	            ctxt->_work_queue.push(scheduled_op);
191	        }
192	        ctxt->_work_sync._cond_var.notify_one();
193	    }
194	    _num_pending_ops++;
195	}
196	
197	std::shared_ptr<struct io_op_desc_t> deepspeed_io_handle_t::_wait_for_aio_work()
198	{
199	    std::shared_ptr<struct io_op_desc_t> completed_op = nullptr;
200	    for (auto& ctxt : _thread_contexts) {
201	        std::unique_lock<std::mutex> lock(ctxt->_complete_sync._mutex);
202	        ctxt->_complete_sync._cond_var.wait(lock,
203	                                            [ctxt] { return !ctxt->_complete_queue.empty(); });
204	        completed_op = ctxt->_complete_queue.front();
205	        ctxt->_complete_queue.pop();
206	    }
207	    return completed_op;
208	}
209	
210	void deepspeed_io_handle_t::_stop_threads()
211	{
212	    std::lock_guard<std::mutex> lock(_handle_mutex);
213	    assert(0 == _num_pending_ops);
214	    for (auto& ctxt : _thread_contexts) {
215	        {
216	            std::lock_guard<std::mutex> lock(ctxt->_work_sync._mutex);
217	            ctxt->_time_to_exit = true;
218	        }
219	        ctxt->_work_sync._cond_var.notify_one();
220	    }
221	}
