229	int deepspeed_io_handle_t::_wait_locked()
230	{
231	    assert(_num_pending_ops > 0);
232	    auto num_completed_ops = 0;
233	    std::string error_message;
234	    std::exception_ptr finish_error = nullptr;
235	
236	    // Complete every pending op, also after one failed, so that the handle can be used again.
237	    while (_num_pending_ops > 0) {
238	        auto completed_op = _wait_for_aio_work();
239	
240	        try {
241	            if (completed_op->_validate) { completed_op->validate(); }
242	
243	            completed_op->finish();
244	        } catch (...) {
245	            if (!finish_error) { finish_error = std::current_exception(); }
246	        }
247	
248	        if (!completed_op->_filename.empty()) { close(completed_op->_fd); }
249	
250	        const auto error_code = completed_op->_error_code.load();
251	        if (error_code != 0 && error_message.empty()) {
252	            const auto file = completed_op->_filename.empty()
253	                                  ? "fd " + std::to_string(completed_op->_fd)
254	                                  : completed_op->_filename;
255	            error_message = std::string(completed_op->_read_op ? "read from " : "write to ") +
256	                            file + " failed: " + strerror(-error_code);
257	        }
258	
259	        --_num_pending_ops;
260	        ++num_completed_ops;
261	    }
262	
263	    if (!error_message.empty()) { throw std::runtime_error("deepspeed_aio: " + error_message); }
264	    if (finish_error) { std::rethrow_exception(finish_error); }
265	    return num_completed_ops;
266	}
