268	bool deepspeed_io_handle_t::_is_valid_parallel_aio_op(const bool read_op, const int64_t num_bytes)
269	{
270	    const auto op_string = read_op ? "Read" : "Write";
271	    if (num_bytes % get_intra_op_parallelism()) {
272	        std::cout << "deepspeed_aio failure: parallel " << op_string << " num_bytes = " << num_bytes
273	                  << " not divisible by intra op parallelism = " << get_intra_op_parallelism()
274	                  << std::endl;
275	        return false;
276	    }
277	
278	    return true;
279	}
