299	int deepspeed_io_handle_t::_pread(const torch::Tensor& buffer,
300	                                  const int fd,
301	                                  const char* filename,
302	                                  const bool validate,
303	                                  const bool async,
304	                                  const int64_t file_offset)
305	{
306	    std::lock_guard<std::mutex> lock(_handle_mutex);
307	    auto scheduled_op = _create_io_op_desc(true, buffer, fd, filename, validate, file_offset);
