38	
39	#define DEBUG_DS_AIO_PERF 0
40	#define DEBUG_DS_AIO_SUBMIT_PERF 0
41	
42	static const std::string c_library_name = "deepspeed_aio";
43	
44	static void _report_aio_statistics(const char* tag,
45	                                   const std::vector<std::chrono::duration<double>>& latencies)
46	    __attribute__((unused));
47	
48	static void _report_aio_statistics(const char* tag,
49	                                   const std::vector<std::chrono::duration<double>>& latencies)
50	{
51	    std::vector<double> lat_usec;
52	    for (auto& lat : latencies) { lat_usec.push_back(lat.count() * 1e6); }
53	    const auto min_lat = *(std::min_element(lat_usec.begin(), lat_usec.end()));
54	    const auto max_lat = *(std::max_element(lat_usec.begin(), lat_usec.end()));
55	    const auto avg_lat = std::accumulate(lat_usec.begin(), lat_usec.end(), 0) / lat_usec.size();
56	
57	    std::cout << c_library_name << ": latency statistics(usec) " << tag
58	              << " min/max/avg = " << min_lat << " " << max_lat << " " << avg_lat << std::endl;
59	}
60	
61	static void _get_aio_latencies(std::vector<std::chrono::duration<double>>& raw_latencies,
62	                               struct deepspeed_aio_latency_t& summary_latencies)
63	{
64	    std::vector<double> lat_usec;
65	    for (auto& lat : raw_latencies) { lat_usec.push_back(lat.count() * 1e6); }
66	    summary_latencies._min_usec = *(std::min_element(lat_usec.begin(), lat_usec.end()));
67	    summary_latencies._max_usec = *(std::max_element(lat_usec.begin(), lat_usec.end()));
68	    summary_latencies._avg_usec =
69	        std::accumulate(lat_usec.begin(), lat_usec.end(), 0) / lat_usec.size();
70	}
71	
72	// The submit and complete helpers keep the first failure in error_code, as a negative errno.
73	
74	static int64_t _do_io_submit_singles(const int64_t n_iocbs,
75	                                     const int64_t iocb_index,
76	                                     std::unique_ptr<aio_context>& aio_ctxt,
77	                                     std::vector<std::chrono::duration<double>>& submit_times,
78	                                     int& error_code)
79	{
80	    for (auto i = 0; i < n_iocbs; ++i) {
81	        const auto st = std::chrono::high_resolution_clock::now();
82	        const auto submit_ret = io_submit(aio_ctxt->_io_ctxt, 1, aio_ctxt->_iocbs.data() + i);
83	        submit_times.push_back(std::chrono::high_resolution_clock::now() - st);
84	#if DEBUG_DS_AIO_SUBMIT_PERF
85	        printf("submit(usec) %f io_index=%lld buf=%p len=%lu off=%llu \n",
86	               submit_times.back().count() * 1e6,
87	               iocb_index,
88	               aio_ctxt->_iocbs[i]->u.c.buf,
89	               aio_ctxt->_iocbs[i]->u.c.nbytes,
90	               aio_ctxt->_iocbs[i]->u.c.offset);
91	#endif
92	        if (submit_ret != 1) {
93	            if (error_code == 0) { error_code = (submit_ret < 0) ? submit_ret : -EIO; }
94	            return i;
95	        }
96	    }
97	    return n_iocbs;
98	}
99	
100	static int64_t _do_io_submit_block(const int64_t n_iocbs,
101	                                   const int64_t iocb_index,
102	                                   std::unique_ptr<aio_context>& aio_ctxt,
103	                                   std::vector<std::chrono::duration<double>>& submit_times,
104	                                   int& error_code)
105	{
106	    const auto st = std::chrono::high_resolution_clock::now();
107	    const auto submit_ret = io_submit(aio_ctxt->_io_ctxt, n_iocbs, aio_ctxt->_iocbs.data());
108	    submit_times.push_back(std::chrono::high_resolution_clock::now() - st);
109	#if DEBUG_DS_AIO_SUBMIT_PERF
110	    printf("submit(usec) %f io_index=%lld nr=%lld buf=%p len=%lu off=%llu \n",
111	           submit_times.back().count() * 1e6,
112	           iocb_index,
113	           n_iocbs,
114	           aio_ctxt->_iocbs[0]->u.c.buf,
115	           aio_ctxt->_iocbs[0]->u.c.nbytes,
116	           aio_ctxt->_iocbs[0]->u.c.offset);
117	#endif
118	    if (submit_ret == n_iocbs) { return n_iocbs; }
119	    if (error_code == 0) { error_code = (submit_ret < 0) ? submit_ret : -EIO; }
120	    return std::max<int64_t>(submit_ret, 0);
121	}
122	
123	static int64_t _do_io_complete(const int64_t min_completes,
124	                               const int64_t max_completes,
125	                               std::unique_ptr<aio_context>& aio_ctxt,
126	                               std::vector<std::chrono::duration<double>>& reap_times,
127	                               int& error_code)
128	{
129	    const auto start_time = std::chrono::high_resolution_clock::now();
130	    int64_t n_completes;
131	    // A signal handler, e.g. for SIGCHLD of a data loader worker, can interrupt the wait on any
132	    // thread.
133	    do {
134	        n_completes = io_pgetevents(aio_ctxt->_io_ctxt,
135	                                    min_completes,
136	                                    max_completes,
137	                                    aio_ctxt->_io_events.data(),
138	                                    nullptr,
139	                                    nullptr);
140	    } while (n_completes == -EINTR);
141	    reap_times.push_back(std::chrono::high_resolution_clock::now() - start_time);
142	    assert(n_completes >= min_completes);
143	
144	    // The kernel reports a failed request, e.g. an O_DIRECT buffer it cannot use, only in res: a
145	    // negative errno, or fewer bytes than requested. data has the requested size from when the iocb
146	    // was submitted; the iocb itself may have been prepared for another request since.
147	    for (int64_t i = 0; i < n_completes; ++i) {
148	        const auto& event = aio_ctxt->_io_events[i];
149	        const auto num_bytes = static_cast<long>(event.res);
150	        if (num_bytes != reinterpret_cast<intptr_t>(event.data) && error_code == 0) {
151	            error_code = (num_bytes < 0) ? num_bytes : -EIO;
152	        }
153	    }
154	    return n_completes;
155	}
