157	int do_aio_operation_sequential(const bool read_op,
158	                                std::unique_ptr<aio_context>& aio_ctxt,
159	                                std::unique_ptr<io_xfer_ctxt>& xfer_ctxt,
160	                                deepspeed_aio_config_t* config,
161	                                deepspeed_aio_perf_t* perf)
162	{
163	    struct io_prep_context prep_ctxt(read_op, xfer_ctxt, aio_ctxt->_block_size, &aio_ctxt->_iocbs);
164	
165	    const auto num_io_blocks = static_cast<int64_t>(
166	        ceil(static_cast<double>(xfer_ctxt->_num_bytes) / aio_ctxt->_block_size));
167	#if DEBUG_DS_AIO_PERF
168	    const auto io_op_name = std::string(read_op ? "read" : "write");
169	    std::cout << c_library_name << ": start " << io_op_name << " " << xfer_ctxt->_num_bytes
170	              << " bytes with " << num_io_blocks << " io blocks" << std::endl;
171	#endif
172	
173	    std::vector<std::chrono::duration<double>> submit_times;
174	    std::vector<std::chrono::duration<double>> reap_times;
175	    const auto max_queue_bytes =
176	        static_cast<int64_t>(aio_ctxt->_queue_depth * aio_ctxt->_block_size);
177	    int error_code = 0;
178	
179	    auto start = std::chrono::high_resolution_clock::now();
180	    for (int64_t iocb_index = 0; iocb_index < num_io_blocks && error_code == 0;
181	         iocb_index += aio_ctxt->_queue_depth) {
182	        const auto start_offset = iocb_index * aio_ctxt->_block_size;
183	        const auto start_buffer = (char*)xfer_ctxt->_mem_buffer + start_offset;
184	        const auto n_iocbs =
185	            min(static_cast<int64_t>(aio_ctxt->_queue_depth), (num_io_blocks - iocb_index));
186	        const auto num_bytes = min(max_queue_bytes, (xfer_ctxt->_num_bytes - start_offset));
187	        prep_ctxt.prep_iocbs(n_iocbs, num_bytes, start_buffer, start_offset);
188	
189	        const auto n_submitted =
190	            config->_single_submit
191	                ? _do_io_submit_singles(n_iocbs, iocb_index, aio_ctxt, submit_times, error_code)
192	                : _do_io_submit_block(n_iocbs, iocb_index, aio_ctxt, submit_times, error_code);
193	
194	        if (n_submitted > 0) {
195	            _do_io_complete(n_submitted, n_submitted, aio_ctxt, reap_times, error_code);
196	        }
197	    }
198	    const std::chrono::duration<double> elapsed = std::chrono::high_resolution_clock::now() - start;
199	
200	    if (perf) {
201	        _get_aio_latencies(submit_times, perf->_submit);
202	        _get_aio_latencies(reap_times, perf->_complete);
203	        perf->_e2e_usec = elapsed.count() * 1e6;
204	        perf->_e2e_rate_GB = (xfer_ctxt->_num_bytes / elapsed.count() / 1e9);
205	    }
206	
207	#if DEBUG_DS_AIO_PERF
208	    _report_aio_statistics("submit", submit_times);
209	    _report_aio_statistics("complete", reap_times);
210	#endif
211	
212	#if DEBUG_DS_AIO_PERF
213	    std::cout << c_library_name << ": runtime(usec) " << elapsed.count() * 1e6
214	              << " rate(GB/sec) = " << (xfer_ctxt->_num_bytes / elapsed.count() / 1e9) << std::endl;
215	#endif
216	
217	#if DEBUG_DS_AIO_PERF
218	    std::cout << c_library_name << ": finish " << io_op_name << " " << xfer_ctxt->_num_bytes
219	              << " bytes " << std::endl;
220	#endif
221	    return error_code;
222	}
