224	int do_aio_operation_overlap(const bool read_op,
225	                             std::unique_ptr<aio_context>& aio_ctxt,
226	                             std::unique_ptr<io_xfer_ctxt>& xfer_ctxt,
227	                             deepspeed_aio_config_t* config,
228	                             deepspeed_aio_perf_t* perf)
229	{
230	    struct io_prep_generator io_gen(read_op, xfer_ctxt, aio_ctxt->_block_size);
231	
232	#if DEBUG_DS_AIO_PERF
233	    const auto io_op_name = std::string(read_op ? "read" : "write");
234	    std::cout << c_library_name << ": start " << io_op_name << " " << xfer_ctxt->_num_bytes
235	              << " bytes with " << io_gen._num_io_blocks << " io blocks" << std::endl;
236	#endif
237	
238	    std::vector<std::chrono::duration<double>> submit_times;
239	    std::vector<std::chrono::duration<double>> reap_times;
240	
241	    auto request_iocbs = aio_ctxt->_queue_depth;
242	    int64_t n_pending_iocbs = 0;
243	    const auto min_completes = 1;
244	    int error_code = 0;
245	    auto start = std::chrono::high_resolution_clock::now();
246	    while (true) {
247	        // After a failure, only the requests in flight are completed.
248	        const auto n_iocbs = (error_code == 0) ? io_gen.prep_iocbs(request_iocbs - n_pending_iocbs,
249	                                                                   &aio_ctxt->_iocbs)
250	                                               : 0;
251	        if (n_iocbs > 0) {
252	            const auto iocb_index = io_gen._next_iocb_index - n_iocbs;
253	            n_pending_iocbs +=
254	                config->_single_submit
255	                    ? _do_io_submit_singles(n_iocbs, iocb_index, aio_ctxt, submit_times, error_code)
256	                    : _do_io_submit_block(n_iocbs, iocb_index, aio_ctxt, submit_times, error_code);
257	        }
258	
259	        assert(n_pending_iocbs <= aio_ctxt->_queue_depth);
260	
261	        if (n_pending_iocbs == 0) { break; }
262	
263	        const auto n_complete =
264	            _do_io_complete(min_completes, n_pending_iocbs, aio_ctxt, reap_times, error_code);
265	        n_pending_iocbs -= n_complete;
266	    }
267	
268	    const std::chrono::duration<double> elapsed = std::chrono::high_resolution_clock::now() - start;
269	
270	    if (perf) {
271	        _get_aio_latencies(submit_times, perf->_submit);
272	        _get_aio_latencies(reap_times, perf->_complete);
273	        perf->_e2e_usec = elapsed.count() * 1e6;
274	        perf->_e2e_rate_GB = (xfer_ctxt->_num_bytes / elapsed.count() / 1e9);
275	    }
276	
277	#if DEBUG_DS_AIO_PERF
278	    _report_aio_statistics("submit", submit_times);
279	    _report_aio_statistics("complete", reap_times);
280	#endif
281	
282	#if DEBUG_DS_AIO_PERF
283	    std::cout << c_library_name << ": runtime(usec) " << elapsed.count() * 1e6
284	              << " rate(GB/sec) = " << (xfer_ctxt->_num_bytes / elapsed.count() / 1e9) << std::endl;
285	#endif
286	
287	#if DEBUG_DS_AIO_PERF
288	    std::cout << c_library_name << ": finish " << io_op_name << " " << xfer_ctxt->_num_bytes
289	              << " bytes " << std::endl;
290	#endif
291	    return error_code;
292	}
