301	int open_file(const char* filename, const bool read_op)
302	{
303	    const int flags = read_op ? (O_RDONLY | O_DIRECT) : (O_WRONLY | O_CREAT | O_DIRECT);
304	#if defined(__ENABLE_CANN__)
305	    int* flags_ptr = (int*)&flags;
306	    *flags_ptr = read_op ? (O_RDONLY) : (O_WRONLY | O_CREAT);
307	#endif
308	    const int mode = 0600;
309	    const auto fd = open(filename, flags, mode);
310	    if (fd == -1) {
311	        const auto error_code = errno;
312	        const auto error_msg = read_op ? " open for read " : " open for write ";
313	        report_file_error(filename, error_msg, error_code);
314	        return -1;
315	    }
316	    return fd;
