319	int64_t get_io_memory_alignment(const int fd)
320	{
321	    const auto flags = fcntl(fd, F_GETFL);
322	    if (flags == -1 || !(flags & O_DIRECT)) { return 1; }
323	
324	    // Linux 6.1+ reports the alignment of each file: often 4 bytes on NVMe, 512 on md RAID and LVM.
325	    // Older kernels need the logical block size, assumed to be 512 as elsewhere in DeepNVMe.
326	    int64_t alignment = 512;
327	#if defined(STATX_DIOALIGN)
328	    struct statx stx;
329	    if (statx(fd, "", AT_EMPTY_PATH, STATX_DIOALIGN, &stx) == 0 &&
330	        (stx.stx_mask & STATX_DIOALIGN) && stx.stx_dio_mem_align > 0) {
331	        alignment = stx.stx_dio_mem_align;
332	    }
333	#endif
334	    return alignment;
335	}
336	
337	int regular_read(const char* filename, std::vector<char>& buffer)
338	{
339	    const auto fd = open(filename, O_RDONLY, 0600);
340	    assert(fd != -1);
341	    struct stat fs;
342	    const auto result = fstat(fd, &fs);
343	    assert(result != -1);
344	    int64_t num_bytes = fs.st_size;
345	    buffer.resize(num_bytes);
346	    int64_t read_bytes = 0;
347	    auto r = 0;
348	    do {
349	        const auto buffer_ptr = buffer.data() + read_bytes;
350	        const auto bytes_to_read = num_bytes - read_bytes;
351	        r = read(fd, buffer_ptr, bytes_to_read);
352	        read_bytes += r;
353	    } while (r > 0);
354	
355	    if (read_bytes != num_bytes) {
356	        std::cerr << "read error " << " read_bytes (read) = " << read_bytes
357	                  << " num_bytes (fstat) = " << num_bytes << std::endl;
358	    }
359	    assert(read_bytes == num_bytes);
360	    close(fd);
361	    return 0;
362	}
363	
364	static bool _validate_buffer(const char* filename, void* aio_buffer, const int64_t num_bytes)
365	{
366	    std::vector<char> regular_buffer;
367	    const auto reg_ret = regular_read(filename, regular_buffer);
368	    assert(0 == reg_ret);
369	    std::cout << "regular read of " << filename << " returned " << regular_buffer.size() << " bytes"
370	              << std::endl;
371	
372	    if (static_cast<int64_t>(regular_buffer.size()) != num_bytes) { return false; }
373	
374	    return (0 == memcmp(aio_buffer, regular_buffer.data(), regular_buffer.size()));
375	}
376	
377	bool validate_aio_operation(const bool read_op,
378	                            const char* filename,
379	                            void* aio_buffer,
380	                            const int64_t num_bytes)
381	{
382	    const auto msg_suffix = std::string("deepspeed_aio_") +
383	                            std::string(read_op ? "read()" : "write()") +
384	                            std::string("using read()");
385	
386	    if (false == _validate_buffer(filename, aio_buffer, num_bytes)) {
387	        std::cout << "Fail: correctness of " << msg_suffix << std::endl;
388	        return false;
389	    }
390	
391	    std::cout << "Pass: correctness of  " << msg_suffix << std::endl;
392	    return true;
393	}
