39	}
40	
41	char* cpu_op_desc_t::data_ptr() const { return (char*)_contiguous_buffer.data_ptr(); }
42	
43	void cpu_op_desc_t::finish()
44	{
45	    if (_use_bounce_buffer) {
46	        if (_read_op) {
47	            if (_buffer.is_cuda()) {
48	                _buffer.copy_(_cpu_buffer.to(torch::Device(torch::kCUDA, _buffer.get_device()),
49	                                             /*non_blocking=*/true));
50	            }
51	            if (_buffer.is_xpu()) { _buffer.copy_(_cpu_buffer.to(torch::kXPU)); }
52	            if (_buffer.is_cpu()) { _buffer.copy_(_cpu_buffer); }
53	#if defined(__ENABLE_CANN__)
54	            // `DS_BUILD_OPS=1 install.sh` complains that ‘torch_npu’ has not
55	            // been declared, so inline `torch_npu::utils::is_npu`.
56	            if (_buffer.is_privateuseone()) {
57	                auto device = at::Device("npu:0");
58	                _buffer.copy_(_cpu_buffer.to(device));
59	            }
60	#endif
61	        }
62	
63	        _free_bounce_buffer();
64	    }
65	}
66	
67	void cpu_op_desc_t::validate()
68	{
69	    const auto num_io_bytes = static_cast<int64_t>(_contiguous_buffer.nbytes());
70	    validate_aio_operation(_read_op, _filename.c_str(), data_ptr(), num_io_bytes);
71	}
72	
73	void cpu_op_desc_t::run(const int tid,
74	                        std::unique_ptr<aio_context>& aio_ctxt,
75	                        deepspeed_aio_config_t* aio_config)
76	{
77	    assert(tid < _intra_op_parallelism);
78	    const auto buffer_base_offset = _num_bytes_per_thread * tid;
79	    const auto file_base_offset = _file_offset + (_num_bytes_per_thread * tid);
80	
81	    std::unique_ptr<io_xfer_ctxt> xfer_ctxt(new io_xfer_ctxt(
82	        _fd, file_base_offset, buffer_base_offset, _num_bytes_per_thread, data_ptr()));
83	
84	    const auto error_code =
85	        aio_config->_overlap_events
86	            ? do_aio_operation_overlap(_read_op, aio_ctxt, xfer_ctxt, aio_config, nullptr)
87	            : do_aio_operation_sequential(_read_op, aio_ctxt, xfer_ctxt, aio_config, nullptr);
88	    if (error_code != 0) { set_error(error_code); }
89	}
90	
91	void cpu_op_desc_t::_alloc_bounce_buffer()
92	{
93	    auto options = torch::TensorOptions()
94	                       .dtype(_buffer.dtype())
95	                       .layout(_buffer.layout())
96	                       .device(torch::kCPU)
97	                       .requires_grad(false);
98	
99	#if defined(__CUDA_ARCH__)
100	    _cpu_buffer = torch::empty(_buffer.numel(), options).pin_memory();
101	#else
102	    _is_managed_bounce_buffer = true;
103	    _cpu_buffer = _pinned_tensor_mgr->alloc(_buffer.numel(), options);
104	#endif
105	    // The copies to and from the buffer need its shape.
106	    _cpu_buffer = _cpu_buffer.view(_buffer.sizes());
107	}
108	
109	void cpu_op_desc_t::_free_bounce_buffer()
110	{
111	    if (_is_managed_bounce_buffer) { _pinned_tensor_mgr->free(_cpu_buffer); }
112	}
