12	namespace {
13	// Warn home users only once per process: repeatedly offloading data (e.g. hidden
14	// states) to a consumer SSD can exhaust its rated write endurance (TBW).
15	std::once_flag write_warning_flag;
16	
17	constexpr const char* write_warning_emitted_attr = "_deepspeed_nvme_write_warning_emitted";
18	constexpr const char* write_warning_message =
19	    "Offloading to NVMe can generate heavy write traffic. On consumer/home SSDs, repeatedly "
20	    "offloading data (e.g. optimizer states, hidden states) can blow through the drive's "
21	    "rated write endurance (TBW) and shorten its lifespan. Prefer enterprise/datacenter SSDs "
22	    "for sustained offloading workloads.";
23	}  // namespace
24	
25	void warn_consumer_ssd_writes() noexcept
26	{
27	    std::call_once(write_warning_flag, []() noexcept {
28	        try {
29	            // Route through DeepSpeed's Python logger. Acquire the GIL since this may be
30	            // invoked from a non-Python thread. The Python marker keeps the warning
31	            // process-wide even when async_io and gds load separate extension DSOs.
32	            pybind11::gil_scoped_acquire acquire;
33	            auto utils = pybind11::module_::import("deepspeed.utils");
34	            if (pybind11::hasattr(utils, write_warning_emitted_attr)) { return; }
35	
36	            utils.attr(write_warning_emitted_attr) = pybind11::bool_(true);
37	            try {
38	                utils.attr("logger").attr("warning")(write_warning_message);
39	            } catch (pybind11::error_already_set& error) {
40	                error.discard_as_unraisable("DeepSpeed NVMe write endurance warning");
41	            }
42	        } catch (pybind11::error_already_set& error) {
43	            error.discard_as_unraisable("DeepSpeed NVMe write endurance warning");
44	        } catch (...) {
45	            // A best-effort warning must never prevent or alter an I/O operation.
46	        }
47	    });
48	}
