50	io_op_desc_t::io_op_desc_t(const bool read_op,
51	                           const torch::Tensor& buffer,
52	                           const int fd,
53	                           const char* filename,
54	                           const int intra_op_parallelism,
55	                           const bool validate,
56	                           const int64_t file_offset)
57	    : _read_op(read_op),
58	      _buffer(buffer),
59	      _fd(fd),
60	      _filename((filename == nullptr) ? std::string() : filename),
61	      _file_offset(file_offset),
62	      _intra_op_parallelism(intra_op_parallelism),
63	      _num_bytes_per_thread(static_cast<int64_t>(buffer.nbytes()) / intra_op_parallelism),
64	      _validate(validate),
65	      _error_code(0)
66	{
67	    if (validate) { assert(nullptr != filename); }
68	    if (!read_op) { warn_consumer_ssd_writes(); }
69	}
70	
71	void io_op_desc_t::set_error(const int error_code)
72	{
73	    int no_error = 0;
74	    _error_code.compare_exchange_strong(no_error, error_code);
75	}
